# Quick-add a DRAFT claim for the named person, dated the sheet's entry date (else its today) with an empty note; a name new to the
# sheet adds the person first with grade A. One change: a refused quick-add (no name, bad amount, unknown sheet,
# that date in a closed period, or after the person's retirement date, or a new name another sheet of the tree has) adds no person and writes nothing, not even an audit line.
validate:
  class: net.officefloor.hq.app.quickadd.ValidateQuickAdd
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: closed
closed:
  class: net.officefloor.hq.app.quickadd.RefuseClosedQuickAdd
  govern: [ transaction ]
  next: person
person:
  class: net.officefloor.hq.app.quickadd.FindOrAddQuickAddPerson
  govern: [ transaction ]
  next: retired
retired:
  class: net.officefloor.hq.app.claim.RefuseRetiredNewClaim
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveNewClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimAdded
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditClaimRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaimCreated
  govern: [ transaction ]
package net.officefloor.hq.app.quickadd;

import net.officefloor.hq.app.person.AuditPersonAdded;
import net.officefloor.hq.app.person.DuplicatePersonNameException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonRequest;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** The person on the sheet with the name (compared as the person form compares names); when there is none,
 *  add them with grade A (refused when another sheet of the sheet's tree has the name as a name or alias), recording the add and how the figures moved just as the person form does. */
public class FindOrAddQuickAddPerson {
    public void find(@PathVariable("sheetId") String sheetId, @Val PersonRequest request, PersonRepository repository,
            Rollups rollups, Audit audit, Out<Person> person) throws DuplicatePersonNameException {
        String id = sheetId.trim();
        Person found = repository.findByName(id, request.name());
        if (found == null) {
            DuplicatePersonNameException.refuseInTree(id, request.name(), repository);
            var before = rollups.take(id);
            found = repository.insert(id, request.name(), request.grade());
            new AuditPersonAdded().audit(request, found, audit);
            rollups.record(id, request.user(), before);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.quickadd;

/** Body of a quick-add: who is making it, the person's name and the claim's amount as typed. */
public record QuickAddRequest(String user, String name, String amount) {
}
package net.officefloor.hq.app.quickadd;

import net.officefloor.hq.app.period.ClosedPeriodException;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuse the quick-add when the claim's date (the sheet's entry date, else its today) is inside a closed period —
 *  before any person is added, so a refused quick-add leaves nothing behind. */
public class RefuseClosedQuickAdd {
    public void refuse(@PathVariable("sheetId") String sheetId, SheetRepository sheets, PeriodRepository periods)
            throws ClosedPeriodException {
        String id = sheetId.trim();
        periods.lockSheet(id);
        Period closed = periods.closedOn(id, sheets.newClaimDate(id));
        if (closed != null) {
            throw new ClosedPeriodException(closed);
        }
    }
}
package net.officefloor.hq.app.quickadd;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.PersonRequest;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written, by the rules of the person and claim
 *  forms: a name is required (at most 200 characters); the amount is required, a number 0.00 or more with up
 *  to two decimals. Publishes the person as a grade A add (used only when the name is new to the sheet) and
 *  the claim with no date (the sheet's today) and an empty note. */
public class ValidateQuickAdd {
    public void validate(@RequestBody QuickAddRequest request, Out<PersonRequest> person, Out<ClaimInput> claim)
            throws InvalidPersonException, InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (name.length() > 200) {
            throw new InvalidPersonException("A name is at most 200 characters.");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (amount.isEmpty()) {
            throw new InvalidClaimException("An amount is required.");
        }
        if (!amount.matches("\\d{1,12}(\\.\\d{1,2})?")) {
